            if ((double)vertex->y < (double)bounds_max.y) {
                max_y = bounds_max.y;
            } else {
                max_y = vertex->y;
            }
            bounds_max.y = max_y;

            float min_y;
            if ((double)bounds_min.y < (double)vertex->y) {
                min_y = bounds_min.y;
            } else {
                min_y = vertex->y;
            }
            bounds_min.y = min_y;

