// set_subgame_features @ 0x435df0 (thiscall, void)

#include "subgame_runtime.h"

void cRSubGame::SetFeatures()
{
    if (selected_level_record_active != 0) {
        SubSolution* record = selected_level_record;
        runtime_flags = record->runtime_build_flags;
        return;
    }

    int mode = level_mode;
    runtime_flags = SUBGAME_RUNTIME_FLAGS_SWITCH_SEED;
    if ((unsigned int)mode <= 7) {
        runtime_flags = SUBGAME_RUNTIME_FLAGS_ENGINE_DEFAULT;
        switch (mode) {
        case 0:
        case 1:
            runtime_flags = SUBGAME_RUNTIME_FLAGS_POSTAL_CHALLENGE;
            break;
        case 4:
            runtime_flags = SUBGAME_RUNTIME_FLAGS_TIME_TRIAL;
            break;
        case 7:
            runtime_flags = SUBGAME_RUNTIME_FLAGS_TUTORIAL;
            break;
        }
    } else {
        runtime_flags = SUBGAME_RUNTIME_FLAGS_ENGINE_DEFAULT;
    }
}


// switch_track_mirror @ 0x435e60 (thiscall, ret)
// Anti-streak track mirror toggle: randomizes the row mirror flag, but never
// repeats the same state more than 4 times in a row.

#include "subgame_runtime.h"
#include "rmath_random.h"


void cRSubGame::SwitchMirror()
{
    bool mirror_enabled = RAND(1.0f, "Mirror") > 0.5f;
    if (mirror_enabled == track_mirror_enabled)
        ++track_mirror_repeat_count;
    else
        track_mirror_repeat_count = 0;
    if (track_mirror_repeat_count < 4) {
        track_mirror_enabled = mirror_enabled;
        return;
    }
    track_mirror_repeat_count = 0;
    mirror_enabled = !mirror_enabled;
    track_mirror_enabled = mirror_enabled;
}


