            + offsetof(SubTracks, first_segment),
        LEVEL_LAST_SEGMENT_BASE =
            offsetof(cRSubGame, level_definition)
            + offsetof(SubTracks, last_segment),
        SCRATCH_SEGMENT_SLOTS_BASE =
