void cRProgressBar::AI()
{
    GameRoot* game = g_game;
    float progress =
        (game->subgame.embedded_player()->transform.position.z
            - (float)game->subgame.first_block_row_count)
        / ((float)game->subgame.completion_row_start
            - (float)game->subgame.first_block_row_count);
    if (progress < 0.0f) {
        progress = 0.0f;
    } else if (progress > 1.0f) {
        progress = 1.0f;
    }

    float remaining_height = (1.0f - progress) * 232.0f + 12.0f;
    float lit_y = remaining_height + 150.0f;

    tColour color;
    OSDPrintUV(
        0x9d,
        12.0f,
        lit_y - 39.0f,
        64.0f,
        64.0f,
        0x1000000,
        color.Set(1.0f, 1.0f, 1.0f, 1.0f),
        0.0f,
        0.0f,
        1.0f,
        1.0f,
        3,
        0);

    float split_v = remaining_height * 0.00390625f;
    OSDPrintUV(
        0x9b,
        13.0f,
        150.0f,
        64.0f,
        remaining_height,
        0x1000000,
        color.Set(1.0f, 1.0f, 1.0f, 1.0f),
        0.0f,
        0.0f,
        1.0f,
        split_v,
        3,
        0);

    OSDPrintUV(
        0x9c,
        13.0f,
        lit_y,
        64.0f,
        256.0f - remaining_height,
        0x1000000,
        color.Set(1.0f, 1.0f, 1.0f, 1.0f),
        0.0f,
        split_v,
        1.0f,
        1.0f,
        3,
        0);
