void cRSubGame::Complete(unsigned char completed)
{
    player.ScoreStatsDisplay();

    current_high_score_record.run_records[replay_update_cursor].flags |= 0x08;
    ++current_high_score_record.replay_sample_count;
    ++replay_update_cursor;

    if ((g_cheat_state.flags & 1) == 0) {
        SubSolution* record = &current_high_score_record;

        current_high_score_record.active = 1;
        current_high_score_record.score = player.total_score;
        current_high_score_record.timer = player.stopwatch;
        current_high_score_record.score_tail = player.score_tail;
        current_high_score_record.challenge_speed_value = challenge_speed_value;
        current_high_score_record.challenge_difficulty_value =
            challenge_difficulty_value;
        current_high_score_record.replay_start_cursor = player.replay_start_cursor;
        current_high_score_record.replay_speed_scalar = base_rate;
        current_high_score_record.replay_mode_id = level_mode;
        current_high_score_record.challenge_difficulty_scalar = challenge_difficulty_scalar;
        current_high_score_record.garbage_frequency = garbage_frequency;
        current_high_score_record.salt_frequency = salt_frequency;

        if ((level_mode != 1 || player.replay_start_cursor != 0)
            && !selected_level_record_active
            && completed == 1) {
            switch (level_mode) {
            case 0:
                sub_high_score.AddArcade(record, level_mode_arg);
                break;
            case 1:
                sub_high_score.AddSurvival(record);
                break;
            case 4:
                sub_high_score.AddTimeTrial(
                    record,
                    level_mode_arg,
                    player.completion_handoff_active);
                break;
            }
        }
    }
}


