            g_voice_manager.Play(
                VOICE_SET_FALL, VOICE_PLAY_IF_IDLE, -1);
            unsigned char slug_fall_snapshot = slug_fall_active;
            attachment_exit_gate_a = 1;
            if (!slug_fall_snapshot && transform.position.y < -6.0f)
                presentation.SetAnimation(
                    5, 1, OBJECT_ANIMATION_MODE_UNCHANGED);
        }
        if (transform.position.y < -7.0f && !attachment_exit_gate_b) {
            g_voice_manager.Play(
                VOICE_SET_DYING, VOICE_PLAY_INTERRUPT, -1);
            attachment_exit_gate_b = 1;
            attachment_exit_gate_a = 1;
        }
    }

    if (startup_voice_timer > 0.0f) {
        float advanced = startup_voice_step + startup_voice_timer;
        startup_voice_timer = advanced;
        if (advanced > 1.0f) {
            g_voice_manager.Play(
                VOICE_SET_START, VOICE_PLAY_INTERRUPT, -1);
            startup_voice_timer = 0.0f;
        }
    }

    cRSubGame* commentary_game = game;
    float window_floor = commentary_game->subgame_rate * 0.17f;
    if ((commentary_game->subgame_rate * 0.5f - window_floor) * 0.1f + window_floor
            <= velocity.z
        || window_floor >= velocity.z || attachment_exit_pending
        || click_start.state == CLICK_START_STATE_WAITING_FOR_START) {
        slow_commentary_timer = 0.0f;
    } else {
        float advanced = slow_commentary_step + slow_commentary_timer;
        slow_commentary_timer = advanced;
        if (advanced > 1.0f) {
            slow_commentary_timer = 0.0f;
            g_voice_manager.Play(
                VOICE_SET_SLOW, VOICE_PLAY_AFTER_GLOBAL_COOLDOWN, -1);
        }
    }

    Collision();
    presentation.anim_manager.AI();
    presentation.jetpack_channel.anim_manager.AI();
    presentation.weapon_channels[0].anim_manager.AI();
    presentation.weapon_channels[1].anim_manager.AI();
    presentation.weapon_channels[2].anim_manager.AI();
    game->parcel_manager.AI();
    presentation.AIGoldy();
    SetShootFlags();
    if (g_game->subgame.replay_update_cursor < 10)
        shoot_cooldown_progress = shoot_cooldown_step;

    cRSubGame* emitter_game = game;
    if ((emitter_game->runtime_flags
            & SUBGAME_RUNTIME_FLAG_MOVEMENT_FIRE_EMITTERS)
            != 0
        && !completion_handoff_active
        && !slug_fall_active
        && (click_start.state == CLICK_START_STATE_INACTIVE
            || click_start.state == CLICK_START_STATE_TEARDOWN)) {
        if (shoot_cooldown_progress > 0.0f) {
            float advanced = shoot_cooldown_step + shoot_cooldown_progress;
            shoot_cooldown_progress = advanced;
            if (advanced > 1.0f)
                shoot_cooldown_progress = 0.0f;
        } else if (emitter_game->track_state_latch) {
            if ((emitter_game->selected_level_record_active
                    && (emitter_game->selected_level_record
                            ->run_records[emitter_game->replay_update_cursor].flags & 1))
                || (!emitter_game->selected_level_record_active
                    && (control_source->control_flags_a & INPUT_BUTTON_PRIMARY))) {
                PlayShootSfx();
                Shoot(this);
                shoot_cooldown_progress = shoot_cooldown_step + 0.30000001f;
            } else if ((emitter_game->selected_level_record_active
                    && (emitter_game->selected_level_record
                            ->run_records[emitter_game->replay_update_cursor].flags & 2))
                || (!emitter_game->selected_level_record_active
                    && (control_source->control_flags_b & INPUT_BUTTON_PRIMARY))) {
                shoot_cooldown_progress = shoot_cooldown_step;
                PlayShootSfx();
                Shoot(this);
            }
        }
    }

    game->completion.AI();
    cRSubGame* tick_game = game;
    tick_game->current_high_score_record.replay_sample_count =
        tick_game->current_high_score_record.replay_sample_count + 1;
    cRSubGame* cursor_game = game;
    cursor_game->replay_update_cursor = cursor_game->replay_update_cursor + 1;
    cRSubGame* times_game = game;
    if (times_game->replay_update_cursor == 21000)
        times_game->times_up.Init();
    game->times_up.AI();
}

