            slot_cursor->ring.transform.position.x = (random_x + random_x) * 3.0f;
            SubRing* selected_ring = &slot_cursor->ring;
            selected_ring->active_phase =
                RAND(1.0f, "RR7") * 6.28318548f;
            selected_ring->active_phase_step = default_phase_step;
