    switch (score_kind) {
    case SUBGOLDY_SCORE_GARBAGE:
        points = 10;
        break;
    case SUBGOLDY_SCORE_SLUG:
        points = 500;
        break;
    case SUBGOLDY_SCORE_RING:
    case SUBGOLDY_SCORE_PARCEL_COLLECT:
    case SUBGOLDY_SCORE_PARCEL_DELIVER:
        points = 100;
