void cRTime::Add(float delta_ticks)
{
    float delta_seconds = delta_ticks * 0.0166666675f;
    total_seconds += delta_seconds;

    float fraction = second_fraction + delta_seconds;
    second_fraction = fraction;
    if (fraction >= 1.0f) {
        seconds += 1;
