    case CLICK_START_STATE_INACTIVE:
    case CLICK_START_STATE_UNKNOWN_1:
        goto done;
    case CLICK_START_STATE_WAITING_FOR_START:
        goto waiting_for_start;
    case CLICK_START_STATE_START_PENDING:
