    char path[128];

    switch (mode) {
    case 0:
        if (level_index <= 50) {
            sprintf(path, g_arcade_level_format, level_index);
        } else {
            if (level_index == 51)
                sprintf(path, g_arcade_extra_level_path);
        }
        break;

