            sprintf(path, g_time_trial_extra_level_format, level_index - 50);
        break;

    case 1:
        sprintf(path, g_challenge_level_path);
        break;

    case 7:
        sprintf(path, g_tutorial_level_path);
        break;

    case 2:
    case 3:
        sprintf(path, g_arcade000_level_path);
        break;

    default:
        break;
    }

    Init(path);
}


