void cRInvincible::Start()
{
    InvincibleState current_state = state;
    if (current_state != INVINCIBLE_STATE_INACTIVE) {
        if (current_state == INVINCIBLE_STATE_FADING_OUT) {
            state = INVINCIBLE_STATE_FADING_IN;
        }
        return;
    }

    state = INVINCIBLE_STATE_FADING_IN;
    spin_phase = 0.0f;
    spin_phase_step = 0.0333333351f;
    fade_progress = 0.0f;
    fade_step = 0.0333333351f;
    g_game->subgame.player.presentation.invincible_shell.list_flags |=
        BOD_FLAG_RENDER_ENABLED;
    g_audio_backend.play_registered_sound_sample_scaled(0x30, 1.0f);
}


// update_invincible_shell @ 0x444b50 (thiscall, ret)
// Fade/spin controller driven by Goldy's invincibility capability.

#include "game_root.h"
#include "invincible.h"
#include "snail_skin.h"


void cRInvincible::AI()
{
    switch (state) {
    case INVINCIBLE_STATE_INACTIVE:
        if ((g_game->subgame.player.shoot_flags
                & SUBGOLDY_SHOOT_FLAG_INVINCIBLE) != 0) {
            Start();
        } else {
            g_game->subgame.player.presentation.invincible_shell.list_flags &=
                0xffffffdf;
        }
        return;

    case INVINCIBLE_STATE_FADING_IN:
        fade_progress += fade_step;
        if (fade_progress > 1.0f) {
            fade_progress = 1.0f;
            state = INVINCIBLE_STATE_ACTIVE;
        }
        if ((g_game->subgame.player.shoot_flags
                & SUBGOLDY_SHOOT_FLAG_INVINCIBLE) == 0)
            state = INVINCIBLE_STATE_FADING_OUT;
        break;

    case INVINCIBLE_STATE_ACTIVE:
        if ((g_game->subgame.player.shoot_flags
                & SUBGOLDY_SHOOT_FLAG_INVINCIBLE) == 0)
            state = INVINCIBLE_STATE_FADING_OUT;
        break;

    case INVINCIBLE_STATE_FADING_OUT:
        fade_progress -= fade_step;
        if (fade_progress < 0.0f) {
            fade_progress = 0.0f;
            state = INVINCIBLE_STATE_INACTIVE;
            g_game->subgame.player.presentation.snail_skin.Change(
                SNAIL_SKIN_SLOT_DEFAULT, 0.0f);
            return;
        }
        if ((g_game->subgame.player.shoot_flags
                & SUBGOLDY_SHOOT_FLAG_INVINCIBLE) != 0)
            state = INVINCIBLE_STATE_FADING_IN;
        break;
    }

    spin_phase += spin_phase_step;
    if (spin_phase > 1.0f)
        spin_phase -= 1.0f;

    g_game->subgame.player.presentation.snail_skin.Change(
        SNAIL_SKIN_SLOT_INVINCIBLE, 0.0f);
    color.White();
    color.a = fade_progress * 0.80000001f;

    float angle = spin_phase * 6.2831855f;
    transform = g_game->subgame.player.presentation.transform;
    transform.RotLocalY(angle);
}


// handle_subgoldy_collisions @ 0x444cf0 (thiscall, ret) — cRSubGoldy::Collision()
// Eight pool sweeps against the player's cached camera target: salt,
// sub-lazer, garbage (intrusive list), slugs, track rings/parcels, health
// pickups, the speedup and jetpack singles, and the ring-effect ladder.
// The invincibility capability gates salt, garbage knockback, and slug hits.
// Shared idiom: delta z pre-gate < threshold, then the owned Normalize distance.

#include "damage_guage.h"
#include "garbage_hazard_slot.h"
#include "sub_hover.h"
#include "player.h"
#include "ring_special_effect_types.h"
#include "salt_hazard_types.h"
#include "slug_hazard_types.h"
#include "sound_effect_manager.h"
#include "subgame_runtime.h"
#include "sub_lazer_types.h"
#include "track_health_pickup.h"
#include "track_jetpack_pickup.h"
#include "track_parcel_runtime.h"
#include "track_speedup.h"
#include "voice_manager.h"

typedef Vector3 Vec3;

int gRMathRand2();
int sprintf(char* buffer, const char* format, ...);

void cRSubGoldy::Collision()
{
    Vec3 probe_b;      // v67
    Vec3 delta;        // v69
    Vec3 probe_rings;  // v77
    Vec3 probe_fx;     // v78

    if (!attachment_exit_pending && !boost_one_tick && !slug_fall_active) {
        if ((shoot_flags & SUBGOLDY_SHOOT_FLAG_INVINCIBLE) == 0) {
            for (int i = 0;
                 i < (int)(sizeof(game->salt_hazards.slots) / sizeof(cRSalt));
                ++i) {
                if (game->salt_hazards.slots[i].state == 1
                    && game->salt_hazards.slots[i].collision_armed == 1) {
                    Vec3 delta =
                        game->salt_hazards.slots[i].transform.position
                        - cached_camera_target_world;
                    Vec3 probe_salt = delta;
                    if (delta.z < 1.0f && probe_salt.Normalize() < 0.98000002f) {
                        if (damage_retrigger_timer == 0.0f)
                            damage_retrigger_timer = damage_retrigger_step;
                        game->salt_hazards.slots[i].collision_armed = 0;
                        damage_gauge.Take(0.15000001f, 0);
                    }
                }
            }
        }
        for (int j = 0;
             j < SUB_LAZER_SLOT_CAPACITY;
             ++j) {
            if (game->sub_lazers.slots[j].state
                == SUB_LAZER_STATE_ACTIVE) {
                delta.x = game->sub_lazers.slots[j].transform.position.x
                        - cached_camera_target_world.x;
                delta.y = game->sub_lazers.slots[j].transform.position.y
                        - cached_camera_target_world.y;
                delta.z = game->sub_lazers.slots[j].transform.position.z
                        - cached_camera_target_world.z;
                probe_b = delta;
                if (delta.z < 1.0f && probe_b.Normalize() < 0.49000001f) {
                    game->sub_lazers.slots[j].state =
                        SUB_LAZER_STATE_RECYCLE_PENDING;
                    damage_gauge.Take(0.02f, 0);
                }
            }
        }
        for (cRSubGarbage* garbage = game->garbage_hazards.active_head;
             garbage;
             garbage = garbage->next_active) {
            if (garbage->state == SUB_GARBAGE_STATE_ACTIVE) {
                delta =
                    garbage->transform.position - cached_camera_target_world;
                probe_b = delta;
                if (delta.z < 1.0f && probe_b.Normalize() < 0.98000002f) {
                    if ((shoot_flags & SUBGOLDY_SHOOT_FLAG_INVINCIBLE) == 0) {
                        velocity.x = velocity.x - probe_b.x * velocity.z * 0.18000001f;
                        velocity.z = velocity.z - probe_b.z * velocity.z * 0.1f;
                    }
                    garbage->state = SUB_GARBAGE_STATE_BURST_PENDING;
                    if (probe_b.x < 0.0f)
                        garbage->collision_side = SUB_GARBAGE_COLLISION_SIDE_LEFT;
                    else
                        garbage->collision_side = SUB_GARBAGE_COLLISION_SIDE_RIGHT;
                    ScoreAdd(SUBGOLDY_SCORE_GARBAGE, 0);
                    damage_gauge.Take(0.039999999f, 0);
                    g_sound_effect_manager.Play(
                        39 - (int)((float)gRMathRand2()
                            * 0.0000305175781f * -2.0f));
                }
            }
        }
        for (int m = 0; m < SUB_SLUG_SLOT_CAPACITY; ++m) {
            SubSlugState state = game->slug_hazards.slots[m].state;
            if (state == SUB_SLUG_STATE_ACTIVE
                || state == SUB_SLUG_STATE_LATERAL_ACTIVE) {
                Vec3 slug_delta;
                slug_delta =
                    game->slug_hazards.slots[m].transform.position
                    - cached_camera_target_world;
                probe_b = slug_delta;
                if (slug_delta.z < 2.0f) {
                    float distance = probe_b.Normalize();
                    if (distance < 1.5675001f) {
                        if ((shoot_flags & SUBGOLDY_SHOOT_FLAG_INVINCIBLE) == 0) {
                            if (!slug_fall_active) {
                                cRSubGame* hit_game = game;
                                slug_fall_active = 1;
                                follow_state.active = 0;
                                float rate = hit_game->subgame_rate;
                                velocity =
                                    Vector3(0.0f, 0.2f, -0.2f) * rate;
                                FallingInit();
                                presentation.cutscene.state =
                                    CUT_SCENE_STATE_DEATH_PENDING;
                                game->slug_hazards.slots[m]
                                    .player_encounter_latched = 1;
                                game->slug_hazards.slots[m].VoicePlay(
                                    34 - (int)((float)gRMathRand2()
                                        * 0.0000305175781f * -2.0f));
                                float half = distance * 0.5f;
                                presentation.wobble.lift_phase_step = 0.0f;
                                Vec3 burst_offset = probe_b * half;
                                Vec3 burst_sum = burst_offset + cached_camera_target_world;
                                Vec3 burst_position = burst_sum;
                                firework.Shoot(&burst_position, player_slot, 92, 80);
                            } else {
                                float rate = game->subgame_rate;
                                float scaled_rate = rate * rate * 0.0040000002f;
                                velocity.z = scaled_rate * -8.0f;
                                damage_gauge.Take(1.0f, 0);
                            }
                        } else {
                            game->slug_hazards.slots[m].Kill();
                        }
                    }
                }
        }
    }
    for (int n = 0; n < 50; ++n) {
        if (game->parcel_manager.slots[n].state
                == PARCEL_STATE_TRACK_ACTIVE) {
                Vec3 parcel_delta;
                parcel_delta.x =
                    game->parcel_manager.slots[n].position.x
                    - cached_camera_target_world.x;
                parcel_delta.y =
                    game->parcel_manager.slots[n].position.y
                    - cached_camera_target_world.y;
                parcel_delta.z =
                    game->parcel_manager.slots[n].position.z
                    - cached_camera_target_world.z;
                probe_rings = parcel_delta;
                if (parcel_delta.z < 1.0f
                    && probe_rings.Normalize() < 1.24f) {
                    ScoreAdd(SUBGOLDY_SCORE_PARCEL_COLLECT, 0);
                    g_voice_manager.Play(
                        VOICE_SET_PACKAGE, VOICE_PLAY_AFTER_GLOBAL_COOLDOWN, -1);
                    g_sound_effect_manager.Play(27);
                    game->parcel_manager.slots[n].state =
                        PARCEL_STATE_COLLECT_PENDING;
                    cRSubGame* parcel_game = game;
                    int collected = ++parcels_collected;
                    if (!parcel_game->level_mode)
                        sprintf(
                            parcel_game->lives_text_widget->text_buffer,
                            "%i/%i",
                            collected,
                            parcel_game->level_definition.parcel_count);
                }
            }
        }
    }
    Vec3 pickup_probe;
    for (int ii = 0; ii < 8; ++ii) {
        if (game->health_pickups[ii].state == TRACK_PICKUP_STATE_ACTIVE) {
            probe_b.x =
                game->health_pickups[ii].position.x
                - cached_camera_target_world.x;
            probe_b.y =
                game->health_pickups[ii].position.y
                - cached_camera_target_world.y;
            probe_b.z =
                game->health_pickups[ii].position.z
                - cached_camera_target_world.z;
            pickup_probe = probe_b;
            if (transform.position.y >= 0.49000001f && probe_b.z < 1.0f) {
                float pickup_y;
                if (probe_b.y < 0.0f)
                    pickup_y = -probe_b.y;
                else
                    pickup_y = probe_b.y;
                if (pickup_y < 0.40000001f
                    && pickup_probe.Normalize() < 0.98000002f) {
                    g_sound_effect_manager.Play(14);
                    game->health_pickups[ii].state =
                        TRACK_PICKUP_STATE_TEARDOWN_PENDING;
                    HealthCollect(&game->health_pickups[ii]);
                    damage_gauge.Take(-0.5f, 0);
                }
            }
        }
    }
    if (game->speedup_pickup.state == TRACK_PICKUP_STATE_ACTIVE) {
        probe_b.x =
            game->speedup_pickup.transform.position.x
            - cached_camera_target_world.x;
        probe_b.y =
            game->speedup_pickup.transform.position.y
            - cached_camera_target_world.y;
        probe_b.z =
            game->speedup_pickup.transform.position.z
            - cached_camera_target_world.z;
        pickup_probe = probe_b;
        if (transform.position.y >= 0.49000001f && probe_b.z < 1.0f) {
            float pickup_y;
            if (probe_b.y < 0.0f)
                pickup_y = -probe_b.y;
            else
                pickup_y = probe_b.y;
            if (pickup_y < 0.40000001f
                && pickup_probe.Normalize() < 0.98000002f) {
                game->speedup_pickup.state =
                    TRACK_PICKUP_STATE_TEARDOWN_PENDING;
                noop_runtime_ai();
                velocity.z = game->subgame_rate * 0.5f;
            }
        }
    }
    if (game->jetpack_pickup.state == TRACK_PICKUP_STATE_ACTIVE) {
        probe_b.x =
            game->jetpack_pickup.position.x - cached_camera_target_world.x;
        probe_b.y =
            game->jetpack_pickup.position.y - cached_camera_target_world.y;
        probe_b.z =
            game->jetpack_pickup.position.z - cached_camera_target_world.z;
        pickup_probe = probe_b;
        if (transform.position.y >= 0.49000001f && probe_b.z < 1.0f && pickup_probe.Normalize() < 3.0f) {
            game->jetpack_pickup.state =
                TRACK_PICKUP_STATE_TEARDOWN_PENDING;
            sub_hover.On();
        }
    }
    for (int jj = 0; jj < SUB_RING_POOL_CAPACITY; ++jj) {
        if (game->ring_effects.slots[jj].state == SUB_RING_STATE_ACTIVE) {
            Vec3 ring_delta;
            ring_delta.x =
                game->ring_effects.slots[jj].transform.position.x
                - cached_camera_target_world.x;
            ring_delta.y =
                game->ring_effects.slots[jj].transform.position.y
                - cached_camera_target_world.y;
            ring_delta.z =
                game->ring_effects.slots[jj].transform.position.z
                - cached_camera_target_world.z;
            probe_fx = ring_delta;
            if (ring_delta.z < 1.0f) {
                if (probe_fx.Normalize() < 0.98000002f) {
                    game->ring_effects.slots[jj].state =
                        SUB_RING_STATE_COLLECT_PENDING;
                    if (!completion_handoff_active) {
                        cRSubGame* effect_game = game;
                        SubRingKind kind = effect_game->ring_effects.slots[jj].kind;
                        if (kind == SUB_RING_KIND_SLOW_DEFAULT
                            || kind == SUB_RING_KIND_SLOW_AUTHORED) {
                            velocity.z = -0.1f;
                            g_sound_effect_manager.Play(43);
                        } else {
                            velocity.z = effect_game->subgame_rate * 0.5f;
                        }
                    }
                    cRSubGame* ladder_game = game;
                    SubRingKind effect_kind =
                        ladder_game->ring_effects.slots[jj].kind;
                    if (effect_kind == SUB_RING_KIND_NORMAL_DEFAULT
                        || effect_kind == SUB_RING_KIND_NORMAL_AUTHORED) {
                        int current_lives = lives;
                        if (current_lives < 10) {
                            if ((ladder_game->runtime_flags
                                    & SUBGAME_RUNTIME_FLAG_RING_LIFE_REWARD)
                                    != 0
                                && ladder_game->level_mode != 3)
                                lives = current_lives + 1;
                            g_voice_manager.Play(
                                VOICE_SET_POWER_UP,
                                VOICE_PLAY_AFTER_GLOBAL_COOLDOWN,
                                -1);
                        }
                        int tier = shooting_tier;
                        if (tier < 8) {
                            shooting_tier = tier + 1;
                        } else if (tier == 8) {
                            shooting_tier = 7;
                        }
                        int effect_index = shooting_tier - 1;
                        if (effect_index > 6)
                            effect_index = 6;
                        g_sound_effect_manager.Play(effect_index + 1);
                        ScoreAdd(SUBGOLDY_SCORE_RING, 0);
                        continue;
                    }
                    if (effect_kind == SUB_RING_KIND_POWER_UP_AUTHORED) {
                        int tier = shooting_tier;
                        if (tier < 8) {
                            shooting_tier = tier + 1;
                        } else if (tier == 8) {
                            shooting_tier = 7;
                        }
                        int effect_index = shooting_tier - 1;
                        if (effect_index > 6)
                            effect_index = 6;
                        g_sound_effect_manager.Play(effect_index + 1);
                        ScoreAdd(SUBGOLDY_SCORE_RING, 0);
                        continue;
                    }
                    if (effect_kind == SUB_RING_KIND_UNKNOWN_1) {
                        ScoreAdd(SUBGOLDY_SCORE_RING, 0);
                        g_sound_effect_manager.Play(1);
                    } else if (effect_kind == SUB_RING_KIND_EXPLODE_RAMP
                        || effect_kind == SUB_RING_KIND_EXPLODE_AUTHORED) {
                        ScoreAdd(SUBGOLDY_SCORE_RING, 0);
                        g_sound_effect_manager.Play(42);
                        nuke_effect_progress = nuke_effect_progress_step;
                        nuke.Init();
                    }
                }
            }
        }
    }
}


