        case WARNING_STATE_OPAQUE:
            border->hot_text_color.a = 0.99900001f;
            advanced = phase_step + phase;
            phase = advanced;
            if (advanced > 1.0f) {
                phase = 0.0f;
                state = WARNING_STATE_FADING;
            }
