        .transform.position.z = (float)sample_z;
    ((PathTemplateSample *)((char *)secondary + sample_offset))[0]
        .transform.Identity();
    ((PathTemplateSample *)((char *)secondary + sample_offset))[0]
        .transform.position.x =
        ((PathTemplateSample *)((char *)primary + sample_offset))[0]
