    if ((flags & FRONTEND_WIDGET_FLAG_KILL_PENDING) != 0) {
        widget_flags = flags & ~FRONTEND_WIDGET_FLAG_KILL_PENDING;
        g_game->active_bod_list.remove_bod(this);
        tooltip.ReSet();
        widget_flags = 0;
