        ((PathTemplateSample *)((char *)primary + current_offset))[-1]
            .transform.basis_up.Cross(
                ((PathTemplateSample *)((char *)primary +
                                        current_offset))[-1]
                    .transform.basis_forward,
                ((PathTemplateSample *)((char *)primary +
                                        current_offset))[-1]
                    .transform.basis_right);
