            ((PathTemplateSample *)((char *)secondary +
                                    current_offset))[-1]
                .transform.position;
        ((PathTemplateSample *)((char *)secondary + current_offset))[-1]
            .transform.basis_forward.Normalize();
        ((PathTemplateSample *)((char *)secondary + current_offset))[-1]
            .transform.basis_right.Cross(
                ((PathTemplateSample *)((char *)secondary +
                                        current_offset))[-1]
                    .transform.basis_up,
                ((PathTemplateSample *)((char *)secondary +
                                        current_offset))[-1]
